void verify_image_integrity(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image;
  gchar *temp_file_path;
  GimpImage *loaded_image;
  GError *error = NULL;
  gint result;

  image = create_main_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_file_path = g_strdup_temp("image_XXXXXX", NULL);
  result = gimp_file_save(GIMP_RUN_NONINTERACTIVE, image, NULL, NULL, temp_file_path, "PNG", &error);
  g_assert(result == TRUE);
  g_assert(error == NULL);

  loaded_image = gimp_file_load(GIMP_RUN_NONINTERACTIVE, temp_file_path, "PNG", &error);
  g_assert(loaded_image != NULL);
  g_assert(error == NULL);

  g_assert(compare_images(image, loaded_image));

  g_object_unref(loaded_image);
  g_unlink(temp_file_path);
  g_free(temp_file_path);
}

void write_and_verify_image(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image;
  gchar *temp_file_path;
  GError *error = NULL;
  gboolean success;

  image = gimp_image_new_with_flags(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features, &error);
  g_assert_no_error(error);
  g_assert(image != NULL);

  temp_file_path = g_strdup_printf("/tmp/gimp_temp_image_%d.xcf", getpid());

  success = gimp_file_procedure_write("file-xcf-save", image, temp_file_path, NULL, &error);
  g_assert_no_error(error);
  g_assert(success);

  g_object_unref(image);

  image = gimp_file_load(temp_file_path, temp_file_path, &error);
  g_assert_no_error(error);
  g_assert(image != NULL);

  g_object_unref(image);
  g_unlink(temp_file_path);
  g_free(temp_file_path);
}

void verify_image_integrity(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image;
  GFile *temp_file;
  gchar *temp_path;
  GError *error = NULL;

  image = gimp_image_new_with_flags(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_file = g_file_new_tmp("image_XXXXXX.xcf", NULL, &error);
  g_assert(temp_file != NULL);

  temp_path = g_file_get_path(temp_file);
  gimp_image_save(image, temp_path);
  g_free(temp_path);

