  g_assert(loaded_image != NULL);

  g_object_unref(temp_file);
  gimp_image_delete(image);
  gimp_image_delete(loaded_image);
}

void verify_image_integrity(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image;
  gchar *temp_file;
  GimpImage *loaded_image;
  GError *error = NULL;

  image = create_main_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_file = gimp_temp_file("verify-image-XXXXXX", ".xcf");
  g_assert(temp_file != NULL);

  if (!gimp_file_save(GIMP_FILE_SAVE_EXPORT, GIMP_FILE_SAVE_OVERWRITE, "xcf", "XCF", image, NULL, temp_file, &error)) {
    g_assert_no_error(error);
  }

  loaded_image = gimp_file_load(GIMP_FILE_LOAD_IMPORTED, "xcf", "XCF", temp_file, &error);
  g_assert_no_error(error);
  g_assert(loaded_image != NULL);

  g_assert(compare_images(image, loaded_image));

  g_file_delete(temp_file, NULL, NULL);
  g_free(temp_file);
  gimp_image_delete(image);
  gimp_image_delete(loaded_image);
}

void verify_image_integrity(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features) {
  GimpImage *image;
  gchar *temp_file_path;
  GimpImage *loaded_image;
  GError *error = NULL;
  GFile *temp_file = NULL;

  image = create_main_image(gimp, with_unusual_stuff, compat_paths, use_gimp_2_8_features);
  g_assert(image != NULL);

  temp_file_path = gimp_file_procedure_write_file("temp_image.xcf", image, NULL, &error);
  g_assert(temp_file_path != NULL);

  temp_file = g_file_new_for_path(temp_file_path);
  loaded_image = gimp_file_procedure_load_image(temp_file_path, NULL, NULL, &error);
  g_assert(loaded_image != NULL);

  g_assert(compare_images(image, loaded_image));

  g_unlink(temp_file_path);
  g_free(temp_file_path);
  g_object_unref(temp_file);
}
